pub fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // Track the index of the earliest maximum-length sequence seen so far.
    let mut best_idx: Option<usize> = None;
    let mut best_len: usize = 0;

    for (i, s) in strings.iter().enumerate() {
        let len = s.len();
        // Use strict > so ties keep the earliest (smallest index) max.
        if best_idx.is_none() || len > best_len {
            best_idx = Some(i);
            best_len = len;
        }
    }

    // Return a sequence exactly equal in content to one of the inputs.
    // Cloning is necessary because the input is owned by `strings`.
    best_idx.map(|i| strings[i].clone())
}

